#include <print>
#include <memory>
#include <utility>

struct Node {
    int value;
    std::unique_ptr<Node> next;
};

std::unique_ptr<Node> make_node(int v) {
    auto p = std::make_unique<Node>();
    p->value = v;
    return p;
}

int main() {
    auto head = make_node(1);
    head->next = make_node(2);
    head->next->next = make_node(3);

    std::unique_ptr<Node> prev;
    while (head) {
        auto next = std::move(head->next);
        head->next = std::move(prev);
        prev = std::move(head);
        head = std::move(next);

        std::print("本轮后 prev=");
        for (Node* p = prev.get(); p; p = p->next.get()) std::print("{} ", p->value);
        std::print(" head=");
        if (head) std::println("{}", head->value); else std::println("空");
    }

    for (Node* p = prev.get(); p; p = p->next.get()) std::print("{} -> ", p->value);
    std::println("null");
    // 最后一轮 head 走空，新头在 prev
    return 0;
}

